{
  "passageId": "sf-film-society",
  "items": [
    {
      "id": "R1",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "장르의 성쇠와 관습 변화는 영화가 대중의 취향에 반응한다는 일반적 설명을 보여 주는 사례다."
    },
    {
      "id": "R2",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "영화가 반영하는 것을 대중의 취향에서 공유된 이념으로 넓히며 논의를 확장한다."
    },
    {
      "id": "R3",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "영화에 이념이 반영되지만 그것이 투명하게 드러나는 것은 아니라는 한계를 제시한다."
    },
    {
      "id": "R4",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "하나의 매체인 영화 안에 드러냄과 숨김이라는 상반된 성격이 동시에 존재한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "영화가 숨기는 매체라는 설명을 숨겨지는 이념의 성격과 위치로 구체화한다."
    },
    {
      "id": "R6",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "이념이 영화의 이면에 감추어져 있다는 인식상의 한계에 대해 모티브와 이미지의 해석이라는 방법을 제시한다."
    },
    {
      "id": "R7",
      "type": "PROCESS",
      "otherName": "",
      "reason": "이미지 해석으로 읽어 낸 이념을 바탕으로 사회를 이해하는 다음 단계가 진행된다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "독일 영화의 반복적 이미지 해석은 앞서 설명한 이념과 사회의 해석 방법을 구체적으로 보여 주는 사례다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "앞 문단의 이미지 해석과 사회 이해에 관한 내용을 사회의 심층적 이해라는 표현으로 요약하여 다시 말한다."
    },
    {
      "id": "R10",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "영화를 통해 사회를 이해하는 방식에 대해 크라카우어는 이미지 해석을, 제임슨은 서사를 중시한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "사회의 분산성을 근거로 그 총체적 양상을 역사가 된 이후에야 파악할 수 있다고 설명한다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "사회의 파편성을 근거로 그 총체적 양상을 역사가 된 이후에야 파악할 수 있다고 설명한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "역사가 된 사회를 총체적으로 파악할 수 있다는 설명에서 현재도 역사처럼 조망하면 총체적으로 파악할 수 있다는 판단을 도출한다."
    },
    {
      "id": "R14",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "현재를 역사처럼 조망하여 사회를 총체적으로 파악하기 위한 수단으로 서사를 통한 역사화에 주목한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "서사의 회고적 서술 특성을 근거로 서사가 총체적 조망을 가능하게 한다고 설명한다."
    },
    {
      "id": "R16",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "서사를 통한 역사화라는 원리를 미래를 다루는 SF에도 적용한다."
    },
    {
      "id": "R17",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "역사화의 적용 대상으로 언급한 SF를 새로운 중심 화제로 삼아 그 정의와 기준을 설명한다."
    },
    {
      "id": "R18",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "SF가 과학적 지식에 기반하지만 모든 소재와 서사의 과학적 사실성까지 요구되는 것은 아니라고 한정한다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "과학적 사실성이 필수는 아니라는 설명을 실제로 중시되는 기준인 개연성을 제시하여 구체화한다."
    },
    {
      "id": "R20",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "SF에서 중요하다고 한 개연성의 뜻을 설정과 인과 관계의 합리적 납득 가능성으로 풀이한다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "경이로움이라는 장르적 특징을 장대하고 압도적인 대상이 선사하는 경험으로 구체화한다."
    },
    {
      "id": "R22",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "SF의 경이로움이라는 특징을 그것을 안겨 주는 대상인 노붐에 관한 설명으로 구체화한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "일회적 놀라움의 장치가 아니라는 설명을 작품 전반에 영향을 미치는 요소라는 실제 역할로 구체화한다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노붐의 지배적 영향과 세계관을 드러내는 기능을 근거로 진정한 주인공이라고 평가한다."
    },
    {
      "id": "R25",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "SF가 미래를 상상하지만 그 상상의 기반은 작품이 생산된 당대에 있다는 양면성을 제시한다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "미래에 대한 상상이 생산 당시의 시대에 기반한다는 점이 SF를 현실의 반영으로 보는 주장의 근거다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "SF의 상상이 당대에 기반한다는 사실로부터 인물과 시·공간적 설정도 당대 현실과 유사하다는 설명을 도출한다."
    },
    {
      "id": "R28",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 SF의 인물과 설정이 현실과 유사하면서도 다르다는 양면성을 제시한다."
    },
    {
      "id": "R29",
      "type": "CAUSE",
      "otherName": "",
      "reason": "현실을 닮으면서도 다른 SF 세계의 성격이 독자의 인지적 낯섦을 실제로 촉발한다."
    },
    {
      "id": "R30",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "인지적 낯섦이 촉발된다는 설명을 친숙한 현실의 대상을 낯설고 새롭게 느끼는 경험으로 풀어 준다."
    },
    {
      "id": "R31",
      "type": "CAUSE",
      "otherName": "",
      "reason": "SF와 현실의 다름이 친숙한 대상을 낯설고 새롭게 느끼게 하는 원인으로 제시된다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "노붐이 드러내는 현실과 허구 세계의 차이가 낯섦을 유발하는 요인으로 연결된다."
    },
    {
      "id": "R33",
      "type": "CAUSE",
      "otherName": "",
      "reason": "SF의 다름을 인지하여 현실을 낯설게 느끼는 경험이 현실에 대한 거리 두기와 비판적 성찰로 이어진다."
    },
    {
      "id": "R34",
      "type": "CAUSE",
      "otherName": "",
      "reason": "다름의 인지로 생긴 현실과의 거리 두기가 현실을 비판적으로 바라보는 작용으로 이어진다."
    },
    {
      "id": "R35",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "다름의 인지가 비판적 현실 인식을 이끈다는 설명을 근거로 인지적 낯섦을 정서적·지적 체험으로 규정한다."
    },
    {
      "id": "R36",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "미지의 세계에 대한 동경을 충족하는 허구적 이야기 가운데 유토피아 이야기를 특정하여 논의를 구체화한다."
    },
    {
      "id": "R37",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유토피아 이야기와 SF의 유사성 인정이 유토피아를 SF의 중요한 소재로 받아들이는 판단을 뒷받침한다."
    },
    {
      "id": "R38",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "환경 오염과 전쟁으로 인한 인류의 위기가 이상 세계를 탐색하는 SF의 역할이 중요해졌다는 주장의 근거다."
    },
    {
      "id": "R39",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "유토피아라는 소재의 수용에서 오늘날 이상 세계를 탐색하는 SF의 사회적 역할로 논의를 확장한다."
    },
    {
      "id": "R40",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "크라카우어와 수빈은 예술 작품이 그것을 생산한 사회나 현실을 반영한다고 본다는 점에서 공통된다."
    },
    {
      "id": "R41",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "SF를 통한 사회 인식을 제임슨은 역사화에 의한 총체적 조망으로, 수빈은 인지적 낯섦에 의한 비판적 성찰로 설명한다."
    }
  ]
}

